/* From Uiverse.io by AbanoubMagdy1 - Tags: card */
.__UIV_SCOPE__ .card {
  border: .05rem solid black;
  height: 210px;
  width: 180px;
  overflow: hidden;
  position: relative;
}

.__UIV_SCOPE__ .card:hover .img1 {
  transform: scale(1.5, 1.2) translate(5px, -30px) rotate(5deg);
}

.__UIV_SCOPE__ .card:hover .img1::before {
  transition: transform 1s 0.4s;
  transform: translateX(400px) skewX(-10deg);
}

.__UIV_SCOPE__ .card:hover .img2 {
  transform: translateY(120%);
}

.__UIV_SCOPE__ .card .img {
  position: absolute;
  width: 100%;
  height: 50%;
  background: linear-gradient(180deg, rgb(65, 122, 255), rgb(23, 65, 193));
  background-size: 100% 200%;
  transition: 0.3s all;
}

.__UIV_SCOPE__ .card .img1 {
  top: 0;
  right: 0;
  position: relative;
}

.__UIV_SCOPE__ .card .img1::before {
  content: "";
  position: absolute;
  top: 0;
  left: -25px;
  height: 100%;
  width: 10px;
  transform: skewX(-10deg);
  background-image: linear-gradient(to right, rgb(32, 151, 248), rgba(255, 255, 255, 0.9));
}

.__UIV_SCOPE__ .card .img2 {
  bottom: 0;
  right: 0;
  background-position: bottom center;
}

.__UIV_SCOPE__ .card__content {
  margin-left: 1rem;
  margin-top: 1rem;
  transform: translateX(-130%);
  transition: .5s ease-in-out transform .3s;
  position: relative;
  z-index: -1;
}

.__UIV_SCOPE__ .card__content span {
  display: block;
}

.__UIV_SCOPE__ .card__content .name {
  font-weight: bold;
  font-size: 1.7rem;
}

.__UIV_SCOPE__ .card__content .job {
  color: #B2B2B2;
}

.__UIV_SCOPE__ .card:hover .card__content {
  transform: translateX(0);
}
